"""Render the bilingual catalogue's English city pages before localization."""
import json
from pathlib import Path
DATA=json.loads((OUT.parent/'cities.json').read_text())
regions=DATA['regions'];cities=DATA['cities']
all_cities=[dict(slug='toronto',name='Toronto',region='on'),dict(slug='montreal',name='Montréal',region='qc')]+cities

def city_link(c):return link('/'+c['slug']+'/',c['name'],'text-link')
for c in cities:
    name=c['name'];province,_,resource,resource_url,regulator_url=regions[c['region']]
    desc='Find a starting point for intimate and pelvic health care in '+name+'. Explore official health resources, medical registration and questions for your appointment.'
    body=intro('CITY CARE GUIDE','Women’s health care in '+name,desc)
    body+='<section class="wrap city-content"><div class="city-context"><p class="eyebrow">'+province+'</p>'+link('/cities/','Browse all city guides','text-link')+'</div><div class="section-heading"><div><h2>Planning care in '+name+'</h2></div><p>'+c['planning']+'</p></div><h2>Official resources, explained</h2><p class="city-lede">Start with an assessment for your concern. These public resources can help you find a health service or plan a referral; they are not a list of clinics confirmed to perform hymenoplasty.</p><div class="city-resource-grid"><article><span class="eyebrow">01</span><h3>Find local health services</h3><p>Use the official resource below and search by your city or postal code where available. Ask the service about assessment for your specific concern, whether a referral is required, and where the appointment will happen.</p>'+link(resource_url,resource,'text-link')+'</article><article><span class="eyebrow">02</span><h3>Check medical registration</h3><p>Ask for the treating physician’s full name and registration number. Use the relevant regulator to verify their record. A directory entry does not establish experience in a particular procedure or confirm availability.</p>'
    if 'fmrac' in regulator_url:body+='<p>Find the territorial or provincial regulator in the FMRAC member directory, then follow its public registration or contact service.</p>'
    body+=link(regulator_url,'Medical registration · '+province,'text-link')+'</article></div><div class="callout"><h2>Considering hymenoplasty?</h2><p>We have not verified a hymenoplasty provider for this city guide. This does not establish whether the procedure is available locally. Confirm the service, treating clinician, location, full costs and aftercare directly before making plans.</p><p>For evidence, limitations and recovery questions, start with the procedure guide. For symptoms or discomfort, ask a clinician about assessment rather than selecting a cosmetic procedure from a location search.</p>'+link('/hymenoplasty/','Read the hymenoplasty guide','text-link')+'</div><div class="city-resource-grid"><article><h2>Questions to settle before travelling</h2><ul><li>Which appointments require my presence, and at which address?</li><li>Who can assess a problem after I return home?</li><li>What is included in the written quote, and what coverage has actually been confirmed?</li><li>Could an appropriate assessment or non-surgical option be arranged closer to home?</li></ul>'+link('/consultation-guide/','Prepare your consultation questions','text-link')+'</article><article><h2>Looking for a different kind of care?</h2>'+link('/other-services/','Explore specialist care topics','text-link')+'<div class="city-topic-links">'+''.join(link('/'+s+'/',n,'text-link') for s,n in [('hymenectomy','Hymenectomy'),('vaginismus-care','Vaginismus care'),('pessary-fitting','Pessary fitting for prolapse')])+'</div></article></div>'
    siblings=[x for x in all_cities if x['region']==c['region'] and x['slug']!=c['slug']]
    if siblings:body+='<h2>More guides in this province or territory</h2><div class="city-siblings">'+''.join(city_link(x) for x in siblings)+'</div>'
    body+='<p class="fine">Health-resource links checked 8 September 2026. These organisations are not partners or enquiry recipients.</p></section>'
    # The landscape is explicitly illustrative, not a photograph of this city.
    body=body.replace('</section>','</section><figure class="editorial-banner wrap"><img src="/assets/canada.jpg" alt="Illustrative Canadian mountain lake in rose dawn light" width="1536" height="1024" loading="lazy"><figcaption>Local details for your next conversation.</figcaption></figure>',1)
    if c['slug']=='richmond-hill':
        body=body.replace('We have not verified a hymenoplasty provider for this city guide. This does not establish whether the procedure is available locally. Confirm the service, treating clinician, location, full costs and aftercare directly before making plans.', 'For provider research that includes Richmond Hill, see the Toronto guide. Confirm the service, treating clinician, location, full costs and aftercare directly before making plans.')
        body=body.replace('<h2>Considering hymenoplasty?</h2>', '<h2>Considering hymenoplasty?</h2>'+link('/toronto/','Toronto guide','text-link'))
    body+='<section class="cta wrap"><div><p class="eyebrow">YOUR NEXT STEP</p><h2>Ready to discuss your options?</h2><p>Personal questions deserve care and respect. Start a consultation request without sharing intimate history or photographs. The decision to proceed is always yours.</p></div>'+link('/enquiry/','Request a consultation','button light')+'</section>'
    page(c['slug'],'Women’s health care in '+name,desc,body,'care')

controls='<div class="city-controls" hidden><div><label for="city-search">Search cities</label><input id="city-search" type="search" placeholder="City name or province" autocomplete="off"></div><div><label for="city-province">Province or territory filter</label><select id="city-province"><option value="all">All provinces and territories</option>'+''.join('<option value="'+key+'">'+r[0]+'</option>' for key,r in regions.items())+'</select></div><button id="clear-city-filters" class="text-link" type="button">Clear filters</button></div><p id="city-count" role="status" aria-live="polite">60 city guides</p><p id="city-empty" hidden>No matching cities. Try another name or clear the filters.</p>'
groups=''
for key,r in regions.items():
    local=[c for c in all_cities if c['region']==key]
    groups+='<section class="city-group" data-city-group="'+key+'"><h2>'+r[0]+'</h2><div class="city-index-grid">'
    for c in local:
        groups+='<a class="city-index-card" href="/'+c['slug']+'/" data-city-region="'+key+'"><h3>'+c['name']+'</h3><span>'+('Public provider research' if c['slug'] in ('toronto','montreal') else 'Care-navigation guide')+'</span><span aria-hidden="true">↗</span></a>'
    groups+='</div></section>'
body=intro('CITY & REGIONAL GUIDES','Find your city.<br>Find your starting point.','Explore 60 city and urban-area guides across all provinces and territories. Choose a location for care-navigation resources and practical consultation questions.')+'<section class="wrap city-index"><p class="city-lede">City guides explain how to explore care locally. Toronto and Montréal also include researched hymenoplasty provider pages. Other guides link to public health resources; they do not confirm local surgical availability.</p>'+controls+groups+'</section>'
page('cities','Cities across Canada','Find women’s health care-navigation guides for major Canadian cities, with official resources and links to procedure information.',body,'care')
